function uniquePaths(m, n) {
  const dp = new Array(n).fill(1);        // one row, not the full grid
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      dp[j] += dp[j - 1];                 // dp[j] is the row above, dp[j-1] is the left
  return dp[n - 1];
}
